resources.string:
"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">
<html xmlns=\"http://www.w3.org/1999/xhtml\">
<head>
	<meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />
	<meta name=\"viewport\" content=\"initial-scale=1.0, minimum-scale=0.02, maximum-scale=5.0\" />
	<title></title>
	<style type=\"text/css\">
html, body { height:100\%%; padding:0; margin:0; }
div#table { height:100\%%; width:100\%%; display:table; }
div#cell { display:table-cell; vertical-align:middle; text-align:center;}
div#maps { width:{{sizex}}px; height:{{sizey}}px; position:relative; display:inline-block; }
div#playerPosition { position:absolute; z-index:3; font-size:19pt; color:red; text-shadow:rgba(0, 0, 0, 1) 2px 2px 2px; }
img { z-index:1; position:absolute; }
.namedarea { position: absolute; z-index:2; font-size:16pt; text-shadow:black 0.1em 0.1em 0.2em; text-align:center; }
.namedarea span { display:inline-block; vertical-align:middle; line-height:1em; }
.settlement { color:white; }
.other { color:#cccccc; }
	</style>
</head>
<body>

<div id=\"table\">
<div id=\"cell\">
<div id=\"maps\">
{{maps}}
{{areas}}
<div id=\"playerPosition\">x</div>
</div>
</div>
</div>

<script type=\"text/javascript\">
var player = document.getElementById(\"playerPosition\");
var params = window.location.search.substring(1);
if (params) {
\tvar pos = params.split(\",");
\tvar x = parseInt(pos[0])-({{offsetx}});
\tvar y = parseInt(pos[1])-({{offsety}});
\tplayer.style.top = y + \"px\";
\tplayer.style.left = x + \"px\";
} else {
\tplayer.style.display = \"none\";
}

(function() {
\tvar preloadMargin = 768;
\tvar images = document.querySelectorAll(\"img[data-src]\");

\tfunction loadImage(image) {
\t\tvar src = image.getAttribute(\"data-src\");
\t\tif (!src) return;
\t\timage.setAttribute(\"src\", src);
\t\timage.removeAttribute(\"data-src\");
\t}

\tif (\"IntersectionObserver\" in window) {
\t\tvar observer = new IntersectionObserver(function(entries) {
\t\t\tfor (var i = 0; i < entries.length; ++i) {
\t\t\t\tif (entries[i].isIntersecting || entries[i].intersectionRatio > 0) {
\t\t\t\t\tloadImage(entries[i].target);
\t\t\t\t\tobserver.unobserve(entries[i].target);
\t\t\t\t}
\t\t\t}
\t\t}, { rootMargin: preloadMargin + \"px\" });

\t\tfor (var i = 0; i < images.length; ++i) {
\t\t\tobserver.observe(images[i]);
\t\t}
\t} else {
\t\tvar loadScheduled = false;

\t\tfunction loadVisibleImages() {
\t\t\tloadScheduled = false;
\t\t\tvar viewportWidth = document.documentElement.clientWidth || window.innerWidth;
\t\t\tvar viewportHeight = document.documentElement.clientHeight || window.innerHeight;

\t\t\tfor (var i = 0; i < images.length; ++i) {
\t\t\t\tif (!images[i].getAttribute(\"data-src\")) continue;
\t\t\t\tvar rect = images[i].getBoundingClientRect();
\t\t\t\tif (rect.bottom >= -preloadMargin &&
\t\t\t\t\trect.right >= -preloadMargin &&
\t\t\t\t\trect.top <= viewportHeight + preloadMargin &&
\t\t\t\t\trect.left <= viewportWidth + preloadMargin) {
\t\t\t\t\tloadImage(images[i]);
\t\t\t\t}
\t\t\t}
\t\t}

\t\tfunction scheduleLoad() {
\t\t\tif (loadScheduled) return;
\t\t\tloadScheduled = true;
\t\t\twindow.setTimeout(loadVisibleImages, 50);
\t\t}

\t\twindow.addEventListener(\"scroll\", scheduleLoad, false);
\t\twindow.addEventListener(\"resize\", scheduleLoad, false);
\t\tscheduleLoad();
\t}
})();
</script>

</body>
</html>
